1	/**
2	 * FreeLang TCP Native Functions
3	 * Phase 3 Level 3: TCP 소켓 지원 (Node.js net 모듈 활용)
4	 *
5	 * 목표: FFI .so 파일 없이 Node.js net 모듈로 TCP 구현
6	 *
7	 * FFI 대신 JavaScript native 방식:
8	 * - NativeFunctionRegistry에 executor 함수 등록
9	 * - Node.js net.Socket / net.Server 사용
10	 */
11	
12	import * as net from 'net';
13	import { NativeFunctionRegistry } from '../../vm/native-function-registry';
14	import { FFIFunctionSignature } from '../../ffi/type-bindings';
15	
16	/**
17	 * TCP 소켓 및 서버 풀 관리
18	 * ID → Socket/Server 매핑
19	 */
20	class TCPSocketPool {
21	  private nextId = 1000;
22	  private sockets: Map<number, net.Socket> = new Map();
23	  private servers: Map<number, net.Server> = new Map();
24	  private receiveBuffers: Map<number, string> = new Map();  // 수신 데이터 버퍼
25	
26	  /**
27	   * 소켓 등록 및 ID 생성
28	   */
29	  registerSocket(socket: net.Socket): number {
30	    const id = this.nextId++;
31	    this.sockets.set(id, socket);
32	    this.receiveBuffers.set(id, '');
33	
34	    // 데이터 수신 시 버퍼에 저장
35	    socket.on('data', (chunk: Buffer) => {
36	      const buffer = this.receiveBuffers.get(id) || '';
37	      this.receiveBuffers.set(id, buffer + chunk.toString());
38	    });
39	
40	    // 에러 처리
41	    socket.on('error', (err) => {
42	      console.error(`[TCP] Socket ${id} error:`, err.message);
43	    });
44	
45	    // 종료 시 정리
46	    socket.on('close', () => {
47	      this.sockets.delete(id);
48	      this.receiveBuffers.delete(id);
49	    });
50	
51	    return id;
52	  }
53	
54	  /**
55	   * 서버 등록 및 ID 생성
56	   */
57	  registerServer(server: net.Server): number {
58	    const id = this.nextId++;
59	    this.servers.set(id, server);
60	    return id;
61	  }
62	
63	  /**
64	   * 소켓 조회
65	   */
66	  getSocket(id: number): net.Socket | null {
67	    return this.sockets.get(id) || null;
68	  }
69	
70	  /**
71	   * 서버 조회
72	   */
73	  getServer(id: number): net.Server | null {
74	    return this.servers.get(id) || null;
75	  }
76	
77	  /**
78	   * 소켓 종료
79	   */
80	  closeSocket(id: number): void {
81	    const socket = this.sockets.get(id);
82	    if (socket) {
83	      socket.end();
84	      this.sockets.delete(id);
85	      this.receiveBuffers.delete(id);
86	    }
87	  }
88	
89	  /**
90	   * 서버 종료
91	   */
92	  closeServer(id: number): void {
93	    const server = this.servers.get(id);
94	    if (server) {
95	      server.close();
96	      this.servers.delete(id);
97	    }
98	  }
99	
100	  /**
101	   * 수신 버퍼에서 데이터 읽기
102	   */
103	  readBuffer(id: number): string {
104	    const buffer = this.receiveBuffers.get(id) || '';
105	    this.receiveBuffers.set(id, '');  // 읽은 데이터는 버퍼에서 제거
106	    return buffer;
107	  }
108	
109	  /**
110	   * 수신 버퍼에서 1줄 읽기 (CRLF 기준)
111	   */
112	  readLine(id: number): string | null {
113	    const buffer = this.receiveBuffers.get(id) || '';
114	    const index = buffer.indexOf('\n');
115	    if (index === -1) return null;
116	
117	    const line = buffer.substring(0, index + 1);
118	    this.receiveBuffers.set(id, buffer.substring(index + 1));
119	    return line;
120	  }
121	}
