126	/**
127	 * TCP 네이티브 함수 등록
128	 */
129	export function registerTCPFunctions(registry: NativeFunctionRegistry): void {
130	  // ── 서버 함수 ──
131	
132	  /**
133	   * tcp_listen(port: int, backlog: int) → server_id: int
134	   */
135	  registry.register({
136	    name: 'tcp_listen',
137	    module: 'net',
138	    signature: {
139	      name: 'tcp_listen',
140	      returnType: 'int',
141	      parameters: [
142	        { name: 'port', type: 'int' },
143	        { name: 'backlog', type: 'int' }
144	      ],
145	      category: 'stream'
146	    } as FFIFunctionSignature,
147	    executor: (args: any[]) => {
148	      // args: [port, backlog]
149	      const port = args[0] as number;
150	      const backlog = (args[1] as number) || 128;
151	
152	      try {
153	        const server = net.createServer((socket: net.Socket) => {
154	          // 클라이언트 연결 시 자동으로 풀에 등록
155	          socketPool.registerSocket(socket);
156	        });
157	
158	        // server.listen(port, [host], [backlog], [callback])
159	        server.listen(port, '0.0.0.0', backlog, () => {
160	          // 수신 대기 중
161	        });
162	
163	        return socketPool.registerServer(server);
164	      } catch (err: any) {
165	        throw new Error(`tcp_listen failed: ${err.message}`);
166	      }
167	    }
168	  });
169	
170	  /**
171	   * tcp_accept(server_id: int, timeout: int) → socket_id: int
172	   *
173	   * 참고: Node.js 비동기 I/O이므로 완벽한 동기 구현은 불가능.
174	   * 현재는 기본 accept 구현. 실제로는 event-driven 방식으로 수정 필요.
175	   */
176	  registry.register({
177	    name: 'tcp_accept',
178	    module: 'net',
179	    signature: {
180	      name: 'tcp_accept',
181	      returnType: 'int',
182	      parameters: [
183	        { name: 'server_id', type: 'int' },
184	        { name: 'timeout', type: 'int' }
185	      ],
186	      category: 'stream'
187	    } as FFIFunctionSignature,
188	    executor: (args: any[]) => {
189	      const serverId = args[0] as number;
190	      const timeout = args[1] as number;
191	      const server = socketPool.getServer(serverId);
192	      if (!server) {
193	        throw new Error(`Server not found: ${serverId}`);
194	      }
195	      // FFI_NOTE: 비동기 I/O이므로 실제로는 콜백 기반으로 수정 필요
196	      return -1;  // 임시 구현
197	    }
198	  });
199	
200	  // ── 클라이언트 함수 ──
201	
202	  /**
203	   * tcp_connect(host: string, port: int) → socket_id: int
204	   */
205	  registry.register({
206	    name: 'tcp_connect',
207	    module: 'net',
208	    signature: {
209	      name: 'tcp_connect',
210	      returnType: 'int',
211	      parameters: [
212	        { name: 'host', type: 'string' },
213	        { name: 'port', type: 'int' }
214	      ],
215	      category: 'stream'
216	    } as FFIFunctionSignature,
217	    executor: (args: any[]) => {
218	      const host = args[0] as string;
219	      const port = args[1] as number;
220	
221	      try {
222	        const socket = net.createConnection(port, host);
223	        return socketPool.registerSocket(socket);
224	      } catch (err: any) {
225	        throw new Error(`tcp_connect failed: ${err.message}`);
226	      }
227	    }
228	  });
229	
230	  // ── 송수신 함수 ──
231	
232	  /**
233	   * tcp_send(socket_id: int, data: string) → bytes_sent: int
234	   */
235	  registry.register({
236	    name: 'tcp_send',
237	    module: 'net',
238	    signature: {
239	      name: 'tcp_send',
240	      returnType: 'int',
241	      parameters: [
242	        { name: 'socket_id', type: 'int' },
243	        { name: 'data', type: 'string' }
244	      ],
245	      category: 'stream'
246	    } as FFIFunctionSignature,
247	    executor: (args: any[]) => {
248	      const socketId = args[0] as number;
249	      const data = args[1] as string;
250	
251	      const socket = socketPool.getSocket(socketId);
252	      if (!socket) {
253	        throw new Error(`Socket not found: ${socketId}`);
254	      }
255	
256	      try {
257	        const bytes = data.length;
258	        socket.write(data);
259	        return bytes;
260	      } catch (err: any) {
261	        throw new Error(`tcp_send failed: ${err.message}`);
262	      }
263	    }
264	  });
265	
266	  /**
267	   * tcp_recv(socket_id: int, timeout: int) → data: string
268	   *
269	   * timeout (밀리초): 데이터를 기다리는 최대 시간
270	   * 반환: 수신한 데이터 (timeout 시 빈 문자열)
271	   */
272	  registry.register({
273	    name: 'tcp_recv',
274	    module: 'net',
275	    signature: {
276	      name: 'tcp_recv',
277	      returnType: 'string',
278	      parameters: [
279	        { name: 'socket_id', type: 'int' },
280	        { name: 'timeout', type: 'int' }
281	      ],
282	      category: 'stream'
283	    } as FFIFunctionSignature,
284	    executor: (args: any[]) => {
285	      const socketId = args[0] as number;
286	      const timeout = args[1] as number;
287	
288	      const socket = socketPool.getSocket(socketId);
289	      if (!socket) {
290	        throw new Error(`Socket not found: ${socketId}`);
291	      }
292	
293	      try {
294	        // 현재 버퍼의 데이터 반환
295	        // FFI_NOTE: 동기식 read/write가 필요하면 별도 event loop 필요
296	        const data = socketPool.readBuffer(socketId);
297	        return data || '';
298	      } catch (err: any) {
299	        throw new Error(`tcp_recv failed: ${err.message}`);
300	      }
301	    }
302	  });
303	
304	  /**
305	   * tcp_recv_line(socket_id: int, timeout: int) → line: string
306	   *
307	   * CRLF 기준으로 1줄 읽기
308	   */
309	  registry.register({
310	    name: 'tcp_recv_line',
311	    module: 'net',
312	    signature: {
313	      name: 'tcp_recv_line',
314	      returnType: 'string',
315	      parameters: [
316	        { name: 'socket_id', type: 'int' },
317	        { name: 'timeout', type: 'int' }
318	      ],
319	      category: 'stream'
320	    } as FFIFunctionSignature,
321	    executor: (args: any[]) => {
322	      const socketId = args[0] as number;
323	      const timeout = args[1] as number;
324	
325	      const socket = socketPool.getSocket(socketId);
326	      if (!socket) {
327	        throw new Error(`Socket not found: ${socketId}`);
328	      }
329	
330	      try {
331	        const line = socketPool.readLine(socketId);
332	        return line || '';
333	      } catch (err: any) {
334	        throw new Error(`tcp_recv_line failed: ${err.message}`);
335	      }
336	    }
337	  });
338	
339	  // ── 제어 함수 ──
340	
341	  /**
342	   * tcp_close(socket_id: int) → void
343	   */
344	  registry.register({
345	    name: 'tcp_close',
346	    module: 'net',
347	    signature: {
348	      name: 'tcp_close',
349	      returnType: 'int',
350	      parameters: [
351	        { name: 'socket_id', type: 'int' }
352	      ],
353	      category: 'stream'
354	    } as FFIFunctionSignature,
355	    executor: (args: any[]) => {
356	      const socketId = args[0] as number;
357	      socketPool.closeSocket(socketId);
358	      return null;
359	    }
360	  });
361	
362	  /**
363	   * tcp_close_server(server_id: int) → void
364	   */
365	  registry.register({
366	    name: 'tcp_close_server',
367	    module: 'net',
368	    signature: {
369	      name: 'tcp_close_server',
370	      returnType: 'int',
371	      parameters: [
372	        { name: 'server_id', type: 'int' }
373	      ],
374	      category: 'stream'
375	    } as FFIFunctionSignature,
376	    executor: (args: any[]) => {
377	      const serverId = args[0] as number;
378	      socketPool.closeServer(serverId);
379	      return null;
380	    }
381	  });
382	
383	  process.stderr.write('✅ TCP native functions registered\n');
384	}
