2	 * FreeLang Network Module (Phase 16 Week 3)
3	 * TCP/UDP networking with libuv integration
4	 * Uses Promise Bridge for async/await support
5	 */
6	
7	// Callback registry (timer.c pattern)
8	let callback_registry = [];
9	let next_callback_id = 0;
10	
11	fn register_callback(fn) => {
12	  let id = next_callback_id;
13	  next_callback_id = next_callback_id + 1;
14	  callback_registry[id] = fn;
15	  return id;
16	};
17	
18	fn unregister_callback(id) => {
19	  callback_registry[id] = null;
20	};
21	
22	// ────────────────────────────────────────
23	// TCP Server
24	// ────────────────────────────────────────
25	
26	/**
27	 * Create TCP server
28	 * @param port - port number to listen on
29	 * @param onConnection - callback function called when client connects
30	 * @returns Promise that resolves to server handle
31	 */
32	export async fn createServer(port, onConnection) => {
33	  let callback_id = register_callback(onConnection);
34	  let server_id = fl_tcp_server_create(port, callback_id);
35	
36	  if (server_id < 0) {
37	    unregister_callback(callback_id);
38	    throw "Failed to create server";
39	  }
40	
41	  return server_id;
42	};
43	
44	/**
45	 * Close TCP server
46	 * @param server_id - server handle
47	 */
48	export async fn closeServer(server_id) => {
49	  fl_tcp_close(server_id);
50	};
51	
52	// ────────────────────────────────────────
53	// TCP Connection (read/write)
54	// ────────────────────────────────────────
55	
56	/**
57	 * Read data from TCP connection
58	 * @param conn_id - connection handle
59	 * @returns Promise that resolves to received data
60	 */
61	export async fn readData(conn_id) => {
62	  let callback_id = register_callback((data) => data);
63	  fl_tcp_read_start(conn_id, callback_id);
64	
65	  let data = await callback_id;
66	  unregister_callback(callback_id);
67	  return data;
68	};
69	
70	/**
71	 * Write data to TCP connection
72	 * @param conn_id - connection handle
73	 * @param data - data to send
74	 * @returns Promise that resolves when write completes
75	 */
76	export async fn writeData(conn_id, data) => {
77	  let callback_id = register_callback((result) => result);
78	  fl_tcp_write_async(conn_id, data, callback_id);
79	
80	  await callback_id;
81	  unregister_callback(callback_id);
82	};
83	
84	/**
85	 * Close TCP connection
86	 * @param conn_id - connection handle
87	 */
88	export async fn closeConnection(conn_id) => {
89	  fl_tcp_close(conn_id);
90	};
91	
92	/**
93	 * Shutdown TCP connection gracefully
94	 * @param conn_id - connection handle
95	 * @returns Promise that resolves when shutdown completes
96	 */
97	export async fn shutdownConnection(conn_id) => {
98	  let callback_id = register_callback((result) => result);
99	  fl_tcp_shutdown(conn_id, callback_id);
100	
101	  await callback_id;
102	  unregister_callback(callback_id);
103	};
104	
105	// ────────────────────────────────────────
106	// TCP Client
107	// ────────────────────────────────────────
108	
109	/**
110	 * Connect to TCP server
111	 * @param host - host address (IP or hostname)
112	 * @param port - port number
113	 * @returns Promise that resolves to connection handle
114	 */
115	export async fn connect(host, port) => {
116	  let callback_id = register_callback((conn) => conn);
117	  fl_tcp_connect_async(host, port, callback_id);
118	
119	  let conn_id = await callback_id;
120	  unregister_callback(callback_id);
121	  return conn_id;
122	};
123	
124	// ────────────────────────────────────────
125	// UDP Socket
126	// ────────────────────────────────────────
127	
128	/**
129	 * Create UDP socket
130	 * @param port - port number to bind to
131	 * @param onReceive - callback function called when data is received
132	 * @returns Promise that resolves to socket handle
133	 */
134	export async fn createUdpSocket(port, onReceive) => {
135	  let callback_id = register_callback(onReceive);
136	  let socket_id = fl_udp_create(port, callback_id);
137	
138	  if (socket_id < 0) {
139	    unregister_callback(callback_id);
140	    throw "Failed to create UDP socket";
141	  }
142	
143	  fl_udp_recv_start(socket_id, callback_id);
144	  return socket_id;
145	};
146	
147	/**
148	 * Send UDP data
149	 * @param socket_id - socket handle
150	 * @param data - data to send
151	 * @param host - destination host
152	 * @param port - destination port
153	 * @returns Promise that resolves when send completes
154	 */
155	export async fn sendUdp(socket_id, data, host, port) => {
156	  let callback_id = register_callback((result) => result);
157	  fl_udp_send_async(socket_id, data, host, port, callback_id);
158	
159	  await callback_id;
160	  unregister_callback(callback_id);
161	};
162	
163	/**
164	 * Close UDP socket
165	 * @param socket_id - socket handle
166	 */
167	export async fn closeUdpSocket(socket_id) => {
168	  fl_udp_close(socket_id);
169	};
