20	fn ws.onConnection(server, callback) {
21	  // Register callback for new client connections
22	  // server: Server object
23	  // callback: function(client) - called when client connects
24	
25	  if !server.listeners { server.listeners = {} }
26	  server.listeners.connection = callback;
27	  server;
28	}
29	
30	fn ws.onDisconnection(server, callback) {
31	  // Register callback for client disconnections
32	  // server: Server object
33	  // callback: function(client) - called when client disconnects
34	
35	  if !server.listeners { server.listeners = {} }
36	  server.listeners.disconnection = callback;
37	  server;
38	}
