40	fn ws.onMessage(server, callback) {
41	  // Register callback for incoming messages
42	  // server: Server object
43	  // callback: function(client, message) - called when message received
44	
45	  if !server.listeners { server.listeners = {} }
46	  server.listeners.message = callback;
47	  server;
48	}
49	
50	fn ws.onError(server, callback) {
51	  // Register callback for errors
52	  // server: Server object
53	  // callback: function(error) - called on error
54	
55	  if !server.listeners { server.listeners = {} }
56	  server.listeners.error = callback;
57	  server;
