60	fn ws.listen(server) {
61	  // Start listening for WebSocket connections
62	  // server: Server object
63	
64	  server.isListening = true;
65	
66	  // Trigger listening callback if registered
67	  if server.listeners && server.listeners.listening {
68	    server.listeners.listening();
69	  }
70	
71	  server;
