74	fn ws.broadcast(server, message) {
75	  // Send message to all connected clients
76	  // server: Server object
77	  // message: string or object (will be JSON stringified)
78	
79	  let msg = message;
80	  if typeof(message) != "string" {
81	    msg = json.stringify(message);
82	  }
83	
84	  // Broadcast to all clients
85	  let i = 0;
86	  while i < arr.length(server.clients) {
87	    let client = server.clients[i];
88	    try {
89	      ws.send(client, msg);
90	    } catch e {
91	      // Ignore send errors
92	    }
93	    i = i + 1;
94	  }
95	
96	  true;
97	}
