99	fn ws.broadcastExcept(server, excludeClient, message) {
100	  // Broadcast to all clients except one
101	  // server: Server object
102	  // excludeClient: Client to exclude
103	  // message: string or object
104	
105	  let msg = message;
106	  if typeof(message) != "string" {
107	    msg = json.stringify(message);
108	  }
109	
110	  let i = 0;
111	  while i < arr.length(server.clients) {
112	    let client = server.clients[i];
113	    if client.id != excludeClient.id {
114	      try {
115	        ws.send(client, msg);
116	      } catch e {
117	        // Ignore send errors
118	      }
119	    }
120	    i = i + 1;
121	  }
122	
123	  true;
124	}
